-- New Leaf Hearing Care: add the Unitron Moxi S-RX section (insert only) to /unitron-hearing-aids/
-- Applies only if the stored page is still exactly what was reviewed.
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k3em","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3el","text":"Unitron Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k3eo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3en","text":"These are the hearing aid models available from Unitron:","marks":[]}]},{"_type":"block","_key":"unx000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"unx001","text":"Unitron Moxi S-RX","marks":[]}]},{"_type":"block","_key":"unx002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx003","text":"The Unitron Moxi S-RX was released in July 2026 and is Unitron''s first hearing aid with a dedicated AI chip, DEEPSONIC™, built to separate speech from background noise in real time. It''s designed for people who struggle most in busy restaurants, crowded rooms, and group conversations.","marks":[]}]},{"_type":"block","_key":"unx004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx005","text":"The Moxi S-RX is a rechargeable receiver-in-canal (RIC) hearing aid with all-day battery life and universal Bluetooth connectivity. It comes in two technology levels, 9 (premium) and 7 (advanced).","marks":[]}]},{"_type":"block","_key":"unx006","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx007","text":"For people who rarely face noisy, multi-speaker settings, the standard Moxi S-R offers the Smile platform''s core benefits at a lower cost.","marks":[]}]},{"_type":"block","_key":"unx008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx009","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"unx00a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00b","text":"SoundSonic360: AI-powered processing identifies and prioritizes speech from every direction, keeping conversations clear in noisy environments.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"unx00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00d","text":"DEEPSONIC™ AI chip: A dedicated deep neural network chip handles speech-in-noise separation in real time, rather than relying on software alone.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"unx00e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00f","text":"Integra OS automation: Automatically adjusts to changing listening environments, from quiet rooms to loud crowds, with no manual program changes.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"unx00g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00h","text":"AutoFocus 360 (Level 9): Uses all four microphones across both hearing aids to find and enhance speech coming from any direction.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"unx00i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00j","text":"Universal Bluetooth streaming: Stream phone calls, music, and audio directly from smartphones and other devices, with hands-free calling.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"unx00k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"unx00l","text":"Rechargeable convenience: A built-in rechargeable battery delivers reliable all-day power without battery changes.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"k3eq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3ep","text":"Unitron Insera S-R","marks":[]}]},{"_type":"block","_key":"k3es","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3er","text":"Powered by the advanced Smile platform, the Insera S-R is meticulously crafted to fit the unique contours of your ear, offering a discreet design without compromising on power. Whether you’re in a crowded restaurant or a quiet home, its AI-driven technology automatically adjusts to your environment, making hearing feel natural and effortless.","marks":[]}]},{"_type":"block","_key":"k3eu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3et","text":"It comes with robust Bluetooth connectivity and all-day battery life to help you stay connected to the people and devices that matter most.","marks":[]}]},{"_type":"block","_key":"k3ew","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ev","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3ey","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ex","text":"EarMatch™ Customization: An evolved design process that uses deep-fit modeling and intentional microphone placement to optimize sound performance specifically for your unique ear anatomy.","marks":[]}]},{"_type":"block","_key":"k3f0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ez","text":"Universal Bluetooth® Connectivity: Enjoy stable, hands-free calls and high-quality media streaming. The Insera S-R features up to 6x more wireless transmission power and double the connection range of previous models.","marks":[]}]},{"_type":"block","_key":"k3f2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f1","text":"Rechargeable Custom Fit: Combines the “invisible” appeal of a custom-molded hearing aid with the modern convenience of lithium-ion reliability and a magnetic “snap-and-charge” docking station.","marks":[]}]},{"_type":"block","_key":"k3f4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f3","text":"HyperFocus & Speech Enhancement: Advanced spatial features that zoom in on speech during loud conversations while reducing the listening effort required in quieter settings to prevent “listening fatigue.”","marks":[]}]},{"_type":"block","_key":"k3f6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f5","text":"IP68-Rated Durability: Engineered for everyday life with proven wax protection and a rugged, water-resistant design that ensures dependable performance in all conditions.","marks":[]}]},{"_type":"block","_key":"k3f8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3f7","text":"Unitron Moxi S-R","marks":[]}]},{"_type":"block","_key":"k3fa","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3f9","text":"The Unitron Moxi Smile hearing aids are designed to make hearing easier and more natural in everyday situations. They use smart technology called Integra OS, which automatically adjusts to different environments like quiet rooms or noisy restaurants.","marks":[]}]},{"_type":"block","_key":"k3fc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fb","text":"This helps you hear conversations clearly without constantly changing settings. Features like HyperFocus and Speech Enhancement reduce background noise and make soft speech easier to understand, so listening feels less tiring.","marks":[]}]},{"_type":"block","_key":"k3fe","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fd","text":"These hearing aids also offer strong Bluetooth connectivity, allowing you to connect with smartphones, tablets, and TVs. You can enjoy hands-free calls and stream music or shows with clear sound, even when you’re not close to your device. The Moxi Smile aids are rechargeable and come with a portable charger, making them convenient for daily use. Their sleek, water-resistant design ensures they are comfortable and durable for all-day wear.","marks":[]}]},{"_type":"block","_key":"k3fg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ff","text":"Unitron also provides tools to personalize your hearing experience. The Remote Plus app lets you adjust settings and get support from your hearing care professional without visiting the clinic. A “Find My Devices” feature helps you locate misplaced hearing aids. With advanced technology and user-friendly features, Moxi Smile hearing aids aim to enhance your hearing and keep you connected to the moments that matter.","marks":[]}]},{"_type":"block","_key":"k3fi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3fh","text":"Unitron Moxi V-RS","marks":[]}]},{"_type":"block","_key":"k3fk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fj","text":"The Unitron Moxi V-RS is a receiver-in-canal (RIC) hearing aid designed to provide a comfortable, discreet, and high-performance hearing solution. It’s part of Unitron’s Moxi family, known for innovative technology that enhances listening experiences in various environments.","marks":[]}]},{"_type":"block","_key":"k3fm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fl","text":"The Moxi V-RS features automatic sound adjustments that make it easier to hear in both quiet and noisy settings. It also includes connectivity options for smartphones and other Bluetooth-enabled devices, allowing users to stream audio directly to their hearing aids.","marks":[]}]},{"_type":"block","_key":"k3fo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fn","text":"This model is sleek, lightweight, and comes with rechargeable batteries, making it a convenient choice for everyday use. The rechargeable option eliminates the need to replace disposable batteries, offering a more eco-friendly solution. Additionally, the Moxi V-RS provides natural sound quality and speech clarity, ensuring a better understanding of conversations.","marks":[]}]},{"_type":"block","_key":"k3fq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fp","text":"It’s ideal for those looking for advanced hearing technology that’s easy to use and offers a nearly invisible fit behind the ear, making it a perfect choice for active lifestyles.","marks":[]}]},{"_type":"block","_key":"k3fs","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fr","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3fu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ft","text":"Bluetooth Connectivity: With Made For All compatibility and hands-free technology, the Moxi V-RS allows seamless streaming from your favorite Bluetooth-enabled devices. Whether you’re taking calls, listening to music, or watching videos, the audio streams directly to your hearing aids without the need for extra accessories.","marks":[]}]},{"_type":"block","_key":"k3fw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3fv","text":"App/Remote Help: The Remote Plus App lets you take control of your hearing experience. You can easily adjust volume, change settings, and fine-tune your hearing aids based on your environment. For added convenience, Remote Care Assistance allows your hearing healthcare provider to make adjustments remotely, ensuring your devices are always optimized for your hearing needs.","marks":[]}]},{"_type":"block","_key":"k3fy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3fx","text":"Rechargeable Convenience: The Moxi V-RS comes with a rechargeable option, meaning no more hassle of changing disposable batteries. Simply place your hearing aids in the charger, and enjoy a full day of power after just one charge.","marks":[]}]},{"_type":"block","_key":"k3g0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3fz","text":"Unitron Moxi Vivante (V)","marks":[]}]},{"_type":"block","_key":"k3g2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g1","text":"Moxi V is the most recent technology launched by Untrion. With upgraded sound processing in the Integra Operating System (OS), this hearing solution enhances speech from all directions, even in the most challenging environments. When speech is coming from the front, dynamic noise reduction further reduces background noise for conversations even in the most complex situations. The Vivante platform seamlessly makes the subtle nuances of speech more pronounced, making your listening effort easier.","marks":[]}]},{"_type":"block","_key":"k3g4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g3","text":"Unitron Moxi is available in a receiver-in-the-canal (RIC) style. These devices are appropriate for fitting mild-to-profound hearing losses. This product offers a rechargeable lithium-ion battery solution. A disposable size 312 battery option is also available in the previous generation RIC, Moxi Blu (B).","marks":[]}]},{"_type":"block","_key":"k3g6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g5","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3g8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3g7","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3ga","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3g9","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3gc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gb","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3ge","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3gd","text":"Unitron Stride Blu (B)","marks":[]}]},{"_type":"block","_key":"k3gg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gf","text":"Amazing opportunities come out of the blue, and Unitron’s Blu platform of hearing solutions allows you to live in the moment and experience all of life’s opportunities. All Blu devices are powered by the Sonova PRISM™ (Processing Real-time Intelligent Sound Management), which has a chip twice the memory for more connectivity possibilities!","marks":[]}]},{"_type":"block","_key":"k3gi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gh","text":"Unitron Stride B is available in a behind-the-ear (BTE) style. These devices are appropriate for fitting mild to profound hearing losses. This product offers a rechargeable lithium-ion battery solution.","marks":[]}]},{"_type":"block","_key":"k3gk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gj","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3gm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gl","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3go","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gn","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3gq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gp","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3gs","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3gr","text":"Unitron Stride Blu (B) UP","marks":[]}]},{"_type":"block","_key":"k3gu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gt","text":"Living with severe to profound hearing loss can create certain challenges. Life can be unpredictable, but great sound doesn’t have to be. The Unitron Stride B UP devices combine powerful binaural communication (two ears are better than one!) and automatic sound optimization for listening freedom no matter where life takes you.","marks":[]}]},{"_type":"block","_key":"k3gw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gv","text":"Unitron Stride B UP is available in a behind-the-ear (BTE) style. These devices are appropriate for fitting moderate to profound hearing losses. This product offers a disposable size 675 battery.","marks":[]}]},{"_type":"block","_key":"k3gy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gx","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3h0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gz","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3h2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3h1","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3h4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3h3","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3h6","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3h5","text":"Unitron Insera Blu (B)","marks":[]}]},{"_type":"block","_key":"k3h8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3h7","text":"Not all hearing aids are created equal, and Unitron Insera B ensures a custom-fit hearing solution to meet your specific listening needs. The devices are tailored to fit your specific ear anatomy, which translates to improved physical fit and sound quality that mimics a more natural listening experience.","marks":[]}]},{"_type":"block","_key":"k3ha","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3h9","text":"Unitron Insera B devices are appropriate for fitting mild-to-severe hearing losses. The custom fit is created based on your unique ear anatomy and is available in a variety of size options including in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). Depending on the desired hearing aid size the disposable battery option may either be a size 312 or 10.","marks":[]}]},{"_type":"block","_key":"k3hc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hb","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3he","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hd","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3hg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hf","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3hi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hh","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3hk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hj","text":"**Note: Completely-in-the-canal (CIC) and Invisible-in-the-canal (IIC) models do not offer Bluetooth connectivity due to hearing aid size and space limitations.**","marks":["em"]}]},{"_type":"block","_key":"k3hm","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3hl","text":"Assistive Listening Devices & Technology by Unitron","marks":[]}]},{"_type":"block","_key":"k3ho","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hn","text":"Unitron Partner Mic","marks":[]}]},{"_type":"block","_key":"k3hq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hp","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k3hs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hr","text":"TV Connector","marks":[]}]},{"_type":"block","_key":"k3hu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ht","text":"IIC Remote","marks":[]}]},{"_type":"block","_key":"k3is","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3ir","text":"Frequently Asked Questions About Unitron Hearing Aids","marks":[]}]},{"_type":"block","_key":"k3iu","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3it","text":"What is the difference between Unitron Blu and Vivante?","marks":[]}]},{"_type":"block","_key":"k3iw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3iv","text":"Unitron Vivante (V) supersedes Unitron Blu (B) receiver-in-the-canal (RIC) hearing aids. For custom in-the-ear (ITE) hearing aids, Unitron Blu is the most current Unitron product. Unitron Vivante integrates a new design with improved sound quality and a new Remote Plus app.","marks":[]}]},{"_type":"block","_key":"k3iy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3ix","text":"What are the levels of technology in Unitron?","marks":[]}]},{"_type":"block","_key":"k3j0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3iz","text":"The higher the number, the more advanced the technology. Higher levels of technology have more sophisticated sound processing and noise management technology. The higher the level of technology, the more automatic support is available for challenging listening environments.","marks":[]}]},{"_type":"block","_key":"k3j2","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3j1","text":"How long does it take to charge a Unitron hearing aid?","marks":[]}]},{"_type":"block","_key":"k3j4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3j3","text":"Once the green lights blink approximately 5 times, the hearing aids are charging. When the lights stop blinking and turn solid green, the hearing aids are completely charged. This process can take approximately 5-7 hours.","marks":[]}]},{"_type":"block","_key":"k3hw","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3hv","text":"Older Unitron Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k3hy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hx","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k3i0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hz","text":"Unitron Moxi B-R","marks":[]}]},{"_type":"block","_key":"k3i2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i1","text":"Unitron Moxi B-RT","marks":[]}]},{"_type":"block","_key":"k3i4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i3","text":"Unitron Moxi B-312","marks":[]}]},{"_type":"block","_key":"k3i6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i5","text":"Unitron Moxi Fit","marks":[]}]},{"_type":"block","_key":"k3i8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i7","text":"Unitron Moxi Move R","marks":[]}]},{"_type":"block","_key":"k3ia","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i9","text":"Unitron Moxi Jump R T","marks":[]}]},{"_type":"block","_key":"k3ic","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ib","text":"Unitron Insera W 312","marks":[]}]},{"_type":"block","_key":"k3ie","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3id","text":"Unitron Insera 312 Omni","marks":[]}]},{"_type":"block","_key":"k3ig","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3if","text":"Unitron Insera 10 Omni","marks":[]}]},{"_type":"block","_key":"k3ii","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ih","text":"Unitron Insera","marks":[]}]},{"_type":"block","_key":"k3ik","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ij","text":"Unitron Stride P","marks":[]}]},{"_type":"block","_key":"k3im","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3il","text":"Unitron Stride P R","marks":[]}]},{"_type":"block","_key":"k3io","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3in","text":"Unitron Max SP","marks":[]}]},{"_type":"block","_key":"k3iq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ip","text":"Unitron Max UP","marks":[]}]}]', updated_at=datetime('now') WHERE slug='unitron-hearing-aids' AND content='[{"_type":"block","_key":"k3em","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3el","text":"Unitron Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k3eo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3en","text":"These are the hearing aid models available from Unitron:","marks":[]}]},{"_type":"block","_key":"k3eq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3ep","text":"Unitron Insera S-R","marks":[]}]},{"_type":"block","_key":"k3es","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3er","text":"Powered by the advanced Smile platform, the Insera S-R is meticulously crafted to fit the unique contours of your ear, offering a discreet design without compromising on power. Whether you’re in a crowded restaurant or a quiet home, its AI-driven technology automatically adjusts to your environment, making hearing feel natural and effortless.","marks":[]}]},{"_type":"block","_key":"k3eu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3et","text":"It comes with robust Bluetooth connectivity and all-day battery life to help you stay connected to the people and devices that matter most.","marks":[]}]},{"_type":"block","_key":"k3ew","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ev","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3ey","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ex","text":"EarMatch™ Customization: An evolved design process that uses deep-fit modeling and intentional microphone placement to optimize sound performance specifically for your unique ear anatomy.","marks":[]}]},{"_type":"block","_key":"k3f0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ez","text":"Universal Bluetooth® Connectivity: Enjoy stable, hands-free calls and high-quality media streaming. The Insera S-R features up to 6x more wireless transmission power and double the connection range of previous models.","marks":[]}]},{"_type":"block","_key":"k3f2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f1","text":"Rechargeable Custom Fit: Combines the “invisible” appeal of a custom-molded hearing aid with the modern convenience of lithium-ion reliability and a magnetic “snap-and-charge” docking station.","marks":[]}]},{"_type":"block","_key":"k3f4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f3","text":"HyperFocus & Speech Enhancement: Advanced spatial features that zoom in on speech during loud conversations while reducing the listening effort required in quieter settings to prevent “listening fatigue.”","marks":[]}]},{"_type":"block","_key":"k3f6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3f5","text":"IP68-Rated Durability: Engineered for everyday life with proven wax protection and a rugged, water-resistant design that ensures dependable performance in all conditions.","marks":[]}]},{"_type":"block","_key":"k3f8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3f7","text":"Unitron Moxi S-R","marks":[]}]},{"_type":"block","_key":"k3fa","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3f9","text":"The Unitron Moxi Smile hearing aids are designed to make hearing easier and more natural in everyday situations. They use smart technology called Integra OS, which automatically adjusts to different environments like quiet rooms or noisy restaurants.","marks":[]}]},{"_type":"block","_key":"k3fc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fb","text":"This helps you hear conversations clearly without constantly changing settings. Features like HyperFocus and Speech Enhancement reduce background noise and make soft speech easier to understand, so listening feels less tiring.","marks":[]}]},{"_type":"block","_key":"k3fe","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fd","text":"These hearing aids also offer strong Bluetooth connectivity, allowing you to connect with smartphones, tablets, and TVs. You can enjoy hands-free calls and stream music or shows with clear sound, even when you’re not close to your device. The Moxi Smile aids are rechargeable and come with a portable charger, making them convenient for daily use. Their sleek, water-resistant design ensures they are comfortable and durable for all-day wear.","marks":[]}]},{"_type":"block","_key":"k3fg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3ff","text":"Unitron also provides tools to personalize your hearing experience. The Remote Plus app lets you adjust settings and get support from your hearing care professional without visiting the clinic. A “Find My Devices” feature helps you locate misplaced hearing aids. With advanced technology and user-friendly features, Moxi Smile hearing aids aim to enhance your hearing and keep you connected to the moments that matter.","marks":[]}]},{"_type":"block","_key":"k3fi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3fh","text":"Unitron Moxi V-RS","marks":[]}]},{"_type":"block","_key":"k3fk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fj","text":"The Unitron Moxi V-RS is a receiver-in-canal (RIC) hearing aid designed to provide a comfortable, discreet, and high-performance hearing solution. It’s part of Unitron’s Moxi family, known for innovative technology that enhances listening experiences in various environments.","marks":[]}]},{"_type":"block","_key":"k3fm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fl","text":"The Moxi V-RS features automatic sound adjustments that make it easier to hear in both quiet and noisy settings. It also includes connectivity options for smartphones and other Bluetooth-enabled devices, allowing users to stream audio directly to their hearing aids.","marks":[]}]},{"_type":"block","_key":"k3fo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fn","text":"This model is sleek, lightweight, and comes with rechargeable batteries, making it a convenient choice for everyday use. The rechargeable option eliminates the need to replace disposable batteries, offering a more eco-friendly solution. Additionally, the Moxi V-RS provides natural sound quality and speech clarity, ensuring a better understanding of conversations.","marks":[]}]},{"_type":"block","_key":"k3fq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fp","text":"It’s ideal for those looking for advanced hearing technology that’s easy to use and offers a nearly invisible fit behind the ear, making it a perfect choice for active lifestyles.","marks":[]}]},{"_type":"block","_key":"k3fs","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3fr","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3fu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ft","text":"Bluetooth Connectivity: With Made For All compatibility and hands-free technology, the Moxi V-RS allows seamless streaming from your favorite Bluetooth-enabled devices. Whether you’re taking calls, listening to music, or watching videos, the audio streams directly to your hearing aids without the need for extra accessories.","marks":[]}]},{"_type":"block","_key":"k3fw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3fv","text":"App/Remote Help: The Remote Plus App lets you take control of your hearing experience. You can easily adjust volume, change settings, and fine-tune your hearing aids based on your environment. For added convenience, Remote Care Assistance allows your hearing healthcare provider to make adjustments remotely, ensuring your devices are always optimized for your hearing needs.","marks":[]}]},{"_type":"block","_key":"k3fy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3fx","text":"Rechargeable Convenience: The Moxi V-RS comes with a rechargeable option, meaning no more hassle of changing disposable batteries. Simply place your hearing aids in the charger, and enjoy a full day of power after just one charge.","marks":[]}]},{"_type":"block","_key":"k3g0","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3fz","text":"Unitron Moxi Vivante (V)","marks":[]}]},{"_type":"block","_key":"k3g2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g1","text":"Moxi V is the most recent technology launched by Untrion. With upgraded sound processing in the Integra Operating System (OS), this hearing solution enhances speech from all directions, even in the most challenging environments. When speech is coming from the front, dynamic noise reduction further reduces background noise for conversations even in the most complex situations. The Vivante platform seamlessly makes the subtle nuances of speech more pronounced, making your listening effort easier.","marks":[]}]},{"_type":"block","_key":"k3g4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g3","text":"Unitron Moxi is available in a receiver-in-the-canal (RIC) style. These devices are appropriate for fitting mild-to-profound hearing losses. This product offers a rechargeable lithium-ion battery solution. A disposable size 312 battery option is also available in the previous generation RIC, Moxi Blu (B).","marks":[]}]},{"_type":"block","_key":"k3g6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3g5","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3g8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3g7","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3ga","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3g9","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3gc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gb","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3ge","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3gd","text":"Unitron Stride Blu (B)","marks":[]}]},{"_type":"block","_key":"k3gg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gf","text":"Amazing opportunities come out of the blue, and Unitron’s Blu platform of hearing solutions allows you to live in the moment and experience all of life’s opportunities. All Blu devices are powered by the Sonova PRISM™ (Processing Real-time Intelligent Sound Management), which has a chip twice the memory for more connectivity possibilities!","marks":[]}]},{"_type":"block","_key":"k3gi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gh","text":"Unitron Stride B is available in a behind-the-ear (BTE) style. These devices are appropriate for fitting mild to profound hearing losses. This product offers a rechargeable lithium-ion battery solution.","marks":[]}]},{"_type":"block","_key":"k3gk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gj","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3gm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gl","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3go","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gn","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3gq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gp","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3gs","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3gr","text":"Unitron Stride Blu (B) UP","marks":[]}]},{"_type":"block","_key":"k3gu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gt","text":"Living with severe to profound hearing loss can create certain challenges. Life can be unpredictable, but great sound doesn’t have to be. The Unitron Stride B UP devices combine powerful binaural communication (two ears are better than one!) and automatic sound optimization for listening freedom no matter where life takes you.","marks":[]}]},{"_type":"block","_key":"k3gw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gv","text":"Unitron Stride B UP is available in a behind-the-ear (BTE) style. These devices are appropriate for fitting moderate to profound hearing losses. This product offers a disposable size 675 battery.","marks":[]}]},{"_type":"block","_key":"k3gy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3gx","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3h0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3gz","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3h2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3h1","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3h4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3h3","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3h6","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3h5","text":"Unitron Insera Blu (B)","marks":[]}]},{"_type":"block","_key":"k3h8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3h7","text":"Not all hearing aids are created equal, and Unitron Insera B ensures a custom-fit hearing solution to meet your specific listening needs. The devices are tailored to fit your specific ear anatomy, which translates to improved physical fit and sound quality that mimics a more natural listening experience.","marks":[]}]},{"_type":"block","_key":"k3ha","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3h9","text":"Unitron Insera B devices are appropriate for fitting mild-to-severe hearing losses. The custom fit is created based on your unique ear anatomy and is available in a variety of size options including in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). Depending on the desired hearing aid size the disposable battery option may either be a size 312 or 10.","marks":[]}]},{"_type":"block","_key":"k3hc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hb","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k3he","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hd","text":"Bluetooth connectivity: With Made For All compatibility and true hands-free technology, you can stream directly to your hearing aids using your favorite Bluetooth-capable devices.","marks":[]}]},{"_type":"block","_key":"k3hg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hf","text":"App / Remote Help: The Remote Plus App is available for you to customize your listening experience. Whether you need to adjust volume, change settings, or stream music, you can fine-tune your devices to your specific needs. Additionally, Remote Care Assistance is available to have your hearing healthcare provider make adjustments remotely via the app.","marks":[]}]},{"_type":"block","_key":"k3hi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hh","text":"Tinnitus Relief: A noise generator is available to provide a sound enrichment source that stimulates the auditory system.","marks":[]}]},{"_type":"block","_key":"k3hk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hj","text":"**Note: Completely-in-the-canal (CIC) and Invisible-in-the-canal (IIC) models do not offer Bluetooth connectivity due to hearing aid size and space limitations.**","marks":["em"]}]},{"_type":"block","_key":"k3hm","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3hl","text":"Assistive Listening Devices & Technology by Unitron","marks":[]}]},{"_type":"block","_key":"k3ho","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hn","text":"Unitron Partner Mic","marks":[]}]},{"_type":"block","_key":"k3hq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hp","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k3hs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hr","text":"TV Connector","marks":[]}]},{"_type":"block","_key":"k3hu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ht","text":"IIC Remote","marks":[]}]},{"_type":"block","_key":"k3is","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3ir","text":"Frequently Asked Questions About Unitron Hearing Aids","marks":[]}]},{"_type":"block","_key":"k3iu","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3it","text":"What is the difference between Unitron Blu and Vivante?","marks":[]}]},{"_type":"block","_key":"k3iw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3iv","text":"Unitron Vivante (V) supersedes Unitron Blu (B) receiver-in-the-canal (RIC) hearing aids. For custom in-the-ear (ITE) hearing aids, Unitron Blu is the most current Unitron product. Unitron Vivante integrates a new design with improved sound quality and a new Remote Plus app.","marks":[]}]},{"_type":"block","_key":"k3iy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3ix","text":"What are the levels of technology in Unitron?","marks":[]}]},{"_type":"block","_key":"k3j0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3iz","text":"The higher the number, the more advanced the technology. Higher levels of technology have more sophisticated sound processing and noise management technology. The higher the level of technology, the more automatic support is available for challenging listening environments.","marks":[]}]},{"_type":"block","_key":"k3j2","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k3j1","text":"How long does it take to charge a Unitron hearing aid?","marks":[]}]},{"_type":"block","_key":"k3j4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3j3","text":"Once the green lights blink approximately 5 times, the hearing aids are charging. When the lights stop blinking and turn solid green, the hearing aids are completely charged. This process can take approximately 5-7 hours.","marks":[]}]},{"_type":"block","_key":"k3hw","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k3hv","text":"Older Unitron Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k3hy","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k3hx","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k3i0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3hz","text":"Unitron Moxi B-R","marks":[]}]},{"_type":"block","_key":"k3i2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i1","text":"Unitron Moxi B-RT","marks":[]}]},{"_type":"block","_key":"k3i4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i3","text":"Unitron Moxi B-312","marks":[]}]},{"_type":"block","_key":"k3i6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i5","text":"Unitron Moxi Fit","marks":[]}]},{"_type":"block","_key":"k3i8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i7","text":"Unitron Moxi Move R","marks":[]}]},{"_type":"block","_key":"k3ia","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3i9","text":"Unitron Moxi Jump R T","marks":[]}]},{"_type":"block","_key":"k3ic","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ib","text":"Unitron Insera W 312","marks":[]}]},{"_type":"block","_key":"k3ie","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3id","text":"Unitron Insera 312 Omni","marks":[]}]},{"_type":"block","_key":"k3ig","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3if","text":"Unitron Insera 10 Omni","marks":[]}]},{"_type":"block","_key":"k3ii","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ih","text":"Unitron Insera","marks":[]}]},{"_type":"block","_key":"k3ik","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ij","text":"Unitron Stride P","marks":[]}]},{"_type":"block","_key":"k3im","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3il","text":"Unitron Stride P R","marks":[]}]},{"_type":"block","_key":"k3io","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3in","text":"Unitron Max SP","marks":[]}]},{"_type":"block","_key":"k3iq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k3ip","text":"Unitron Max UP","marks":[]}]}]';
